{
  "bioavailability_prediction": "low",
  "confidence": "moderate",
  "revision_action": "keep",
  "supportive_card_ids": ["C05", "C19", "C23"],
  "contradictory_card_ids": ["C10"],
  "prediction_basis_card_ids": ["C05", "C19", "C23"],
  "claims": [
    {
      "claim": "L4 intestinal absorption/permeability records are not nalbuphine-specific: they report morphine salt solubility (C43, C45), hydromorphone dissolution (C40, C41), naltrexone B→A Papp (C44), and unrelated solubility/permeability data (C36-C39, C42, C46, C47), none of which provides an absolute oral F estimate or A→B permeability for the query.",
      "card_ids": ["C36", "C37", "C38", "C39", "C40", "C41", "C42", "C43", "C44", "C45", "C46", "C47"]
    },
    {
      "claim": "The most transferable non-cirrhotic phenolic-opioid comparator, meptazinol, has a cirrhotic F of 27.9±5.3% that is a four-fold increase over controls, implying a control F near 7%; this supports F<20% for a similarly first-pass-liable phenolic opioid such as nalbuphine.",
      "card_ids": ["C05", "C19", "C23"]
    },
    {
      "claim": "High-F contexts are cirrhosis-dependent (pentazocine C04/C11, meperidine C07/C13) or structurally unrelated (paliperidone C01/C15, haloperidol C08/C14, BI 425809 C09, ACT-1004-1239 C03/C06, UDCA C12); ciramadol's high F in cirrhosis (C10) is the only phenolic-opioid counterexample, but it does not establish F≥20% for the non-cirrhotic morphinan query.",
      "card_ids": ["C01", "C03", "C04", "C06", "C07", "C08", "C09", "C10", "C11", "C12", "C13", "C14", "C15"]
    },
    {
      "claim": "L4 solubility/permeability evidence, even where favorable (morphine salt solubility), addresses absorption/dissolution rather than first-pass metabolism and does not change the low prediction.",
      "card_ids": ["C43", "C44", "C45"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "intestinal_absorption_permeability",
      "applicability": "moderate",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C36", "C37", "C38", "C39", "C40", "C41", "C42", "C43", "C44", "C45", "C46", "C47"]
    }
  ],
  "evidence_gaps": [
    "No direct nalbuphine-specific absolute oral bioavailability measurement is present in the supplied records.",
    "No nalbuphine-specific A→B intestinal permeability or solubility measurement is provided; L4 records are for morphine, hydromorphone, naltrexone, estradiol, galantamine, Ro 25-6981, and catechins.",
    "The naltrexone Caco-2 record reports only B→A Papp without an A→B value or efflux ratio, so net absorption cannot be inferred.",
    "The meptazinol control F (~7%) is inferred from the stated four-fold increase over controls rather than reported as a direct numeric control value.",
    "Normal-condition F values for pentazocine, meperidine, and ciramadol are not directly provided; ciramadol's high F in cirrhosis with P>0.05 complicates a simple phenolic-opioid class analogy.",
    "The extent of nalbuphine's first-pass glucuronidation is not quantified in the supplied evidence."
  ],
  "decision_summary": "L4 intestinal absorption/permeability records are mostly for other molecules and do not provide nalbuphine-specific F or A→B permeability; morphine salt solubility and naltrexone B→A Papp do not address first-pass metabolism. The most transferable non-cirrhotic comparator, meptazinol, implies control F near 7%, supporting F<20%; high-F contexts remain cirrhosis-dependent or structurally unrelated. Prediction remains low with moderate confidence."
}

